340	// verifyParent detects a rename or substitution before publishing. The
341	// following operation still uses the original directory descriptor.
342	func (t *Tree) verifyParent(rel string, expected *os.File) error {
343		current, _, err := t.parent(rel, 0)
344		if err != nil {
345			return err
346		}
347		defer current.Close()
348		before, err := expected.Stat()
349		if err != nil {
350			return err
351		}
352		after, err := current.Stat()
353		if err != nil {
354			return err
355		}
356		if !os.SameFile(before, after) {
357			return fmt.Errorf("parent directory changed: %s", rel)
358		}
359		return nil
360	}
