package fs

// Temporary probe against a real SMB mount. Not committed.

import (
	"errors"
	"os"
	"path/filepath"
	"testing"
	"time"

	"golang.org/x/sys/unix"
)

func TestSMBProbe(t *testing.T) {
	remote := os.Getenv("SYNCD_SMB_PROBE")
	if remote == "" {
		t.Skip("set SYNCD_SMB_PROBE")
	}
	r, err := OpenTree(remote)
	if err != nil {
		t.Fatal(err)
	}
	defer r.Close()
	w := func(name, body string) {
		if err := os.WriteFile(filepath.Join(remote, name), []byte(body), 0o644); err != nil {
			t.Fatal(err)
		}
	}

	// 1. Exclusive rename onto an absent name, then onto an existing one.
	w("a", "a")
	w("c", "c")
	t.Logf("renameExclusive a->b (absent):   %v", renameExclusive(r.dir, "a", r.dir, "b"))
	t.Logf("renameExclusive b->c (existing): %v", renameExclusive(r.dir, "b", r.dir, "c"))
	t.Logf("renameExclusive b->B (case of itself): %v", renameExclusive(r.dir, "b", r.dir, "B"))
	names, _ := r.dir.Readdirnames(-1)
	r.dir.Seek(0, 0)
	t.Logf("  dir now: %v", names)

	// 2. Hard links.
	w("h", "h")
	t.Logf("linkat h->h2: %v", unix.Linkat(fd(r.dir), "h", fd(r.dir), "h2", 0))

	// 3. Case-insensitive lookup.
	w("Case.txt", "x")
	_, err = statAt(r.dir, "case.txt")
	t.Logf("statAt(case.txt) with Case.txt present: err=%v", err)

	// 4. Inode stability across a rename into a subdirectory (claimEntry).
	w("ino", "i")
	before, _ := r.Lstat("ino")
	if err := unix.Mkdirat(fd(r.dir), "sub", 0o700); err != nil {
		t.Fatal(err)
	}
	sub, _ := openAt(r.dir, "sub", unix.O_RDONLY|unix.O_DIRECTORY, 0)
	if err := unix.Renameat(fd(r.dir), "ino", fd(sub), "ino"); err != nil {
		t.Fatal(err)
	}
	sub.Close()
	after, _ := r.Lstat("sub/ino")
	t.Logf("inode before=%d after=%d SameEntry=%v", before.Sys().(*unix.Stat_t).Ino, after.Sys().(*unix.Stat_t).Ino, SameEntry(before, after))

	// 5. publishExclusive as shipped (whatever path it takes).
	w("p1", "p1")
	w("p2", "p2")
	err = publishExclusive(r.dir, "p1", r.dir, "p2")
	t.Logf("publishExclusive onto existing: %v (IsExist=%v)", err, os.IsExist(err))
	err = publishExclusive(r.dir, "p1", r.dir, "p3")
	t.Logf("publishExclusive onto absent:   %v", err)

	// 6. mtime preservation through CopyBetween (local -> SMB), sub-second.
	local := t.TempDir()
	src := filepath.Join(local, "m")
	if err := os.WriteFile(src, make([]byte, 8<<20), 0o644); err != nil {
		t.Fatal(err)
	}
	want := time.Unix(1700000000, 123456789)
	if err := os.Chtimes(src, want, want); err != nil {
		t.Fatal(err)
	}
	lt, _ := OpenTree(local)
	defer lt.Close()
	if err := CopyBetween(lt, "m", r, "m"); err != nil {
		t.Fatal(err)
	}
	got, _ := r.Lstat("m")
	t.Logf("mtime want=%s got=%s (unix sec equal=%v)", want.Format(time.RFC3339Nano), got.ModTime().Format(time.RFC3339Nano), got.ModTime().Unix() == want.Unix())

	// 7. A checked delete through a claim (RemoveFrom) on the share.
	w("del", "d")
	info, _ := r.Lstat("del")
	err = (*Trash)(nil).RemoveFrom(r, "del", func(tree *Tree, name string) error {
		cur, err := tree.Lstat(name)
		if err != nil {
			return err
		}
		if !SameEntry(info, cur) {
			return errors.New("identity changed across claim")
		}
		return nil
	})
	_, statErr := r.Lstat("del")
	t.Logf("RemoveFrom with identity check: %v; gone=%v", err, os.IsNotExist(statErr))
}

